    "Антизевковый тренажёр учит формировать ходы-кандидаты, удерживать их внутри коридора безопасности и видеть зоны зевка на заданной глубине.":
        <String>[
      "Антизевковый тренажёр учит формировать ходы-кандидаты, удерживать их внутри коридора безопасности и видеть зоны зевка на заданной глубине.",
      "The anti-blunder trainer teaches you to form candidate moves, keep them inside the safety corridor, and spot blunder zones at the chosen depth.",
      "Der Anti-Patzer-Trainer lehrt, Kandidatenzüge zu bilden, sie im Sicherheitskorridor zu halten und Patzerzonen in der gewählten Tiefe zu erkennen.",
      "L’entraîneur anti-gaffe apprend à former des coups candidats, à les garder dans le corridor de sécurité et à repérer les zones d’erreur à la profondeur choisie.",
      "El entrenador antierrores enseña a formar jugadas candidatas, mantenerlas dentro del corredor de seguridad y detectar zonas de error a la profundidad elegida.",
      "يعلّم مدرب تجنب الأخطاء تكوين النقلات المرشحة وإبقائها داخل ممر الأمان ورؤية مناطق الخطأ بالعمق المحدد.",
      "防漏着训练器教你生成候选着法，让它们保持在安全走廊内，并在设定深度发现漏着区域。",
      "ब्लंडर-रोधी ट्रेनर उम्मीदवार चालें बनाना, उन्हें सुरक्षा गलियारे में रखना और चुनी गई गहराई पर ब्लंडर क्षेत्रों को पहचानना सिखाता है।",
      "駒損防止トレーナーは候補手を作り、安全回廊の中に保ち、設定した深さでミスの領域を見つけることを教えます。",
      "블런더 방지 트레이너는 후보 수를 만들고 안전 구간 안에 유지하며 설정한 깊이에서 블런더 구역을 찾도록 훈련합니다.",
      "Trình luyện chống sai lầm dạy cách tạo các nước ứng viên, giữ chúng trong hành lang an toàn và nhận ra vùng sai lầm ở độ sâu đã chọn.",
