  static String normalizeLanguageCode(String? code) {
    final normalized = (code ?? 'RU').trim().toUpperCase();
    return kMakeChessSupportedLanguageCodes.contains(normalized)
        ? normalized
        : 'RU';
  }

  static MakeChessLanguage language(String? code) {
    final normalized = normalizeLanguageCode(code);
    return kMakeChessLanguages.firstWhere(
      (item) => item.code == normalized,
      orElse: () => kMakeChessLanguages.first,
    );
  }

  static bool isRtl(String? code) => language(code).rtl;

  static TextDirection textDirection(String? code) =>
      isRtl(code) ? TextDirection.rtl : TextDirection.ltr;

  static String? _v5ExactPhrase(String source, String code) {
    final v861AdminRecipientRow = _v861AdminRecipientRows[source];
    if (v861AdminRecipientRow != null) {
      final index = _v4LanguageOrder.indexOf(code);
      if (index >= 0 && index < v861AdminRecipientRow.length) {
        return v861AdminRecipientRow[index];
      }
    }

    final v84AdminCaseRow = _v84AdminCaseRows[source];
    if (v84AdminCaseRow != null) {
      final index = _v4LanguageOrder.indexOf(code);
      if (index >= 0 && index < v84AdminCaseRow.length) {
        return v84AdminCaseRow[index];
      }
    }

    final v8DeleteRow = _v8DeletePhraseRows[source];
    if (v8DeleteRow != null) {
      final index = _v4LanguageOrder.indexOf(code);
      if (index >= 0 && index < v8DeleteRow.length) {
        return v8DeleteRow[index];
      }
    }

    final v8AdminRow = _v8AdminPhraseRows[source];
    if (v8AdminRow != null) {
      final index = _v4LanguageOrder.indexOf(code);
      if (index >= 0 && index < v8AdminRow.length) {
        return v8AdminRow[index];
      }
    }

    final v6Row = _v6PhraseRows[source];
    if (v6Row != null) {
      final index = _v4LanguageOrder.indexOf(code);
      if (index >= 0 && index < v6Row.length) {
        return v6Row[index];
      }
    }

    final v5Row = _v5PhraseRows[source];
    if (v5Row != null) {
      final index = _v4LanguageOrder.indexOf(code);
      if (index >= 0 && index < v5Row.length) {
        return v5Row[index];
      }
    }

    final v4Row = _v4PhraseRows[source];
    if (v4Row != null) {
      final index = _v4LanguageOrder.indexOf(code);
      if (index >= 0 && index < v4Row.length) {
        return v4Row[index];
      }
    }

    final legacyPhrase = _phraseTranslations[code]?[source];
    if (legacyPhrase != null) return legacyPhrase;

    String? matchedKey;
    for (final entry
        in (_translations['RU'] ?? const <String, String>{}).entries) {
      if (entry.value == source) {
        matchedKey = entry.key;
        break;
