  static String? _tournamentV7ExactPhrase(String source, String code) {
    final languageIndex = _v4LanguageOrder.indexOf(code);
    if (languageIndex < 0) return null;
    final row = _tournamentV7PhraseRows[source];
    if (row == null || languageIndex >= row.length) return null;
    return row[languageIndex];
  }

