  static String? _tournamentV7DynamicPhrase(String source, String code) {
    final languageIndex = _v4LanguageOrder.indexOf(code);
    if (languageIndex < 0) return null;

    for (final row in _tournamentV7DynamicRows) {
      final match = RegExp(row.pattern).firstMatch(source);
      if (match == null || match.group(0) != source) continue;
      if (languageIndex >= row.translations.length) continue;

      var result = row.translations[languageIndex];
      for (var groupIndex = 1; groupIndex <= match.groupCount; groupIndex++) {
        final raw = match.group(groupIndex) ?? '';
        final translatedCapture = _tournamentV7ExactPhrase(raw, code) ??
            _v5ExactPhrase(raw, code) ??
            raw;
        result = result.replaceAll('{$groupIndex}', translatedCapture);
      }
      return result;
    }

    return null;
  }

  static String? _v5DynamicPhrase(String source, String code) {
    final languageIndex = _v4LanguageOrder.indexOf(code);
    if (languageIndex < 0) return null;

    for (final row in _v5DynamicPhraseRows) {
      final match = RegExp(row.pattern).firstMatch(source);
      if (match == null || match.group(0) != source) continue;
      if (languageIndex >= row.translations.length) continue;

      var result = row.translations[languageIndex];
      for (var groupIndex = 1; groupIndex <= match.groupCount; groupIndex++) {
        final raw = match.group(groupIndex) ?? '';
        final translatedCapture = _v5ExactPhrase(raw, code) ?? raw;
        result = result.replaceAll(
          '{$groupIndex}',
          translatedCapture,
        );
      }
      return result;
    }

    return null;
  }

  static String phrase(
    String russian, {
    String? languageCode,
    Map<String, Object?> params = const <String, Object?>{},
  }) {
    final code = normalizeLanguageCode(
      languageCode ?? MakeChessLocalizationController.currentCode,
    );

    String? value = _tournamentV7ExactPhrase(russian, code);
    value ??= _v5ExactPhrase(russian, code);
    value ??= _tournamentV7DynamicPhrase(russian, code);
    value ??= _v5DynamicPhrase(russian, code);

    // MAKECHESS_TOURNAMENT_UI_LOCALIZATION_V7_PUNCTUATION_20260807
    // Legacy helper widgets sometimes append ':' before localization,
    // e.g. 'Тип турнира:'. Translate the known UI label and keep punctuation.
    if (value == null && code != 'RU' && russian.endsWith(':')) {
      final core = russian.substring(0, russian.length - 1).trimRight();
      final translatedCore = _tournamentV7ExactPhrase(core, code) ??
          _v5ExactPhrase(core, code) ??
          _tournamentV7DynamicPhrase(core, code) ??
          _v5DynamicPhrase(core, code);
      if (translatedCore != null) value = '$translatedCore:';
    }

    // MAKECHESS_REMAINING_UI_V6_COMPOSITE_FALLBACK_20260807
    // Some legacy widgets build one visible label from several UI fragments
    // separated by bullets. Translate only fragments known to localization;
    // user-created names and unknown data remain unchanged.
    if (value == null && code != 'RU' && russian.contains(' • ')) {
      final parts = russian.split(' • ');
      final translated = <String>[];
      var changed = false;
      for (final part in parts) {
        final localizedPart = _tournamentV7ExactPhrase(part, code) ??
            _v5ExactPhrase(part, code) ??
            _tournamentV7DynamicPhrase(part, code) ??
            _v5DynamicPhrase(part, code) ??
            part;
        if (localizedPart != part) changed = true;
        translated.add(localizedPart);
      }
      if (changed) value = translated.join(' • ');
    }

    value ??= _phraseTranslations['EN']?[russian];

    late String resolved;
    if (value != null) {
      resolved = value;
    } else {
      resolved = russian;
    }

    for (final entry in params.entries) {
      resolved = resolved.replaceAll(
        '{${entry.key}}',
        '${entry.value ?? ''}',
      );
    }

    return resolved;
  }

  static String text(
    String key, {
    String? languageCode,
    Map<String, Object?> params = const <String, Object?>{},
  }) {
    final code = normalizeLanguageCode(
      languageCode ?? MakeChessLocalizationController.currentCode,
    );
    var value =
        _translations[code]?[key] ?? _translations['RU']?[key] ?? '⟦$key⟧';

    for (final entry in params.entries) {
      value = value.replaceAll('{${entry.key}}', '${entry.value ?? ''}');
    }
    return value;
  }

  static void validateOrThrow() {
    final languageCodes = kMakeChessLanguages.map((e) => e.code).toSet();
    final declaredCodes = kMakeChessSupportedLanguageCodes.toSet();
    if (languageCodes.length != kMakeChessLanguages.length ||
        languageCodes.length != declaredCodes.length ||
        !languageCodes.containsAll(declaredCodes)) {
      throw StateError(
        'MakeChess localization: language list contains duplicates or mismatches.',
      );
    }

    for (final code in kMakeChessSupportedLanguageCodes) {
      final table = _translations[code];
      if (table == null) {
        throw StateError(
          'MakeChess localization: translation table $code is missing.',
        );
      }
      final missing = MakeChessTextKey.all.difference(table.keys.toSet());
      final extra = table.keys.toSet().difference(MakeChessTextKey.all);
      if (missing.isNotEmpty || extra.isNotEmpty) {
        throw StateError(
          'MakeChess localization $code: missing=$missing, extra=$extra',
        );
      }
    }
  }
}
